 "content": "from collections import Counter, deque


def transform(grid):
    if not grid:
        return []
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            component = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] != background and
                                (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            rightmost = max(x for _, x in component)
            edge_rows = {y for y, x in component if x == rightmost}
            for y in edge_rows:
                for x in range(rightmost + 1, w):
                    if out[y][x] == background:
                        out[y][x] = 1
    return out


if __name__ == '__main__':
    print('transform loaded')
